    private static final ContainerRowMapper ROW_MAPPER = new ContainerRowMapper();

    private final JdbcTemplate jdbc;

    public ContainerRepository(JdbcTemplate jdbc) {
        this.jdbc = jdbc;
    }

    /**
     * 创建容器，初始版本 0、状态 NORMAL。
     */
    public void insert(String containerKey, String location, LocalDateTime now) {
        jdbc.update("""
                        INSERT INTO container
                            (container_key, location, version, status, created_at, updated_at)
                        VALUES (?, ?, 0, ?, ?, ?)
                        """,
                containerKey, location, ContainerStatus.NORMAL.name(), now, now);
    }

    /**
     * 按业务键查询（不加锁），用于只读场景。
     */
    public Optional<Container> findByKey(String containerKey) {
        List<Container> rows = jdbc.query(
                "SELECT * FROM container WHERE container_key = ?", ROW_MAPPER, containerKey);
        return rows.stream().findFirst();
    }

    /**
     * 按业务键查询并锁定容器行（SELECT ... FOR UPDATE），用于一切版本/状态变更。
     */
    public Optional<Container> findByKeyForUpdate(String containerKey) {
        List<Container> rows = jdbc.query(
                "SELECT * FROM container WHERE container_key = ? FOR UPDATE", ROW_MAPPER, containerKey);
        return rows.stream().findFirst();
    }

    /**
     * 箱内证物放入/移出时版本自增（调用前必须已锁定容器行）。
     */
    public void bumpVersion(String containerKey, LocalDateTime now) {
        jdbc.update(
                "UPDATE container SET version = version + 1, updated_at = ? WHERE container_key = ?",
                now, containerKey);
    }

    /**
     * 更新容器状态（异常隔离 / 复核放行；调用前必须已锁定容器行）。
     */
    public void updateStatus(String containerKey, ContainerStatus status, LocalDateTime now) {
        jdbc.update(
                "UPDATE container SET status = ?, updated_at = ? WHERE container_key = ?",
                status.name(), now, containerKey);
    }

    private static final class ContainerRowMapper implements RowMapper<Container> {
        @Override
        public Container mapRow(ResultSet rs, int rowNum) throws SQLException {
            return new Container(
                    rs.getLong("id"),
                    rs.getString("container_key"),
                    rs.getString("location"),
                    rs.getLong("version"),
                    ContainerStatus.valueOf(rs.getString("status")),
                    rs.getObject("created_at", LocalDateTime.class),
                    rs.getObject("updated_at", LocalDateTime.class));
        }
    }
}

package com.example.starter.evidence;

import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.jdbc.core.RowMapper;
import org.springframework.stereotype.Repository;

import java.sql.ResultSet;
import java.sql.SQLException;
import java.time.LocalDateTime;
import java.util.List;
import java.util.Optional;

/**
 * 容器巡检记录表访问。request_id 全局唯一；记录只追加创建，
 * 第二人确认时一次性写入确认结果与响应快照，之后不再变更。
 */
@Repository
public class ContainerInspectionRepository {

    private static final InspectionRowMapper ROW_MAPPER = new InspectionRowMapper();

    private final JdbcTemplate jdbc;

    public ContainerInspectionRepository(JdbcTemplate jdbc) {
        this.jdbc = jdbc;
    }

    /**
     * 追加一条 PENDING 巡检记录（首位保管人确认）；request_id 冲突时抛出 DuplicateKeyException。
     */
    public void insert(String requestId, String containerKey, long containerVersion,
                       boolean sealIntact, String firstInspector,
                       int responseStatus, String responseBody, LocalDateTime now) {
        jdbc.update("""
                        INSERT INTO container_inspection
                            (request_id, container_key, container_version, seal_intact, status,
                             first_inspector, second_inspector, confirmed_at,
                             response_status, response_body, created_at)
                        VALUES (?, ?, ?, ?, ?, ?, NULL, NULL, ?, ?, ?)
                        """,
                requestId, containerKey, containerVersion, sealIntact ? 1 : 0,
                InspectionStatus.PENDING.name(), firstInspector,
                responseStatus, responseBody, now);
    }

    /**
     * 按巡检请求键查询。
     */
    public Optional<ContainerInspection> findByRequestId(String requestId) {
        List<ContainerInspection> rows = jdbc.query(
                "SELECT * FROM container_inspection WHERE request_id = ?", ROW_MAPPER, requestId);
        return rows.stream().findFirst();
    }

    /**
     * 第二人确认：仅当仍为 PENDING 时写入第二巡检人、确认时刻与确认响应快照。
     *
     * @return 是否成功确认（false 表示已被并发事务先行确认）
     */
    public boolean confirm(long id, String secondInspector, LocalDateTime confirmedAt,
                           int responseStatus, String responseBody) {
        int updated = jdbc.update("""
                        UPDATE container_inspection
                        SET status = ?, second_inspector = ?, confirmed_at = ?,
                            response_status = ?, response_body = ?
                        WHERE id = ? AND status = ?
                        """,
                InspectionStatus.CONFIRMED.name(), secondInspector, confirmedAt,
                responseStatus, responseBody,
                id, InspectionStatus.PENDING.name());
        return updated == 1;
    }

    /**
     * 按容器查询全部巡检记录（按发生顺序），复核放行后历史保留。
     */
    public List<ContainerInspection> findByContainerKey(String containerKey) {
        return jdbc.query(
                "SELECT * FROM container_inspection WHERE container_key = ? ORDER BY id",
                ROW_MAPPER, containerKey);
    }

    private static final class InspectionRowMapper implements RowMapper<ContainerInspection> {
        @Override
        public ContainerInspection mapRow(ResultSet rs, int rowNum) throws SQLException {
            return new ContainerInspection(
                    rs.getLong("id"),
                    rs.getString("request_id"),
                    rs.getString("container_key"),
                    rs.getLong("container_version"),
                    rs.getInt("seal_intact") == 1,
                    InspectionStatus.valueOf(rs.getString("status")),
                    rs.getString("first_inspector"),
                    rs.getString("second_inspector"),
                    rs.getObject("confirmed_at", LocalDateTime.class),
                    rs.getInt("response_status"),
                    rs.getString("response_body"),
                    rs.getObject("created_at", LocalDateTime.class));
        }
    }
}

package com.example.starter.evidence;

import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.jdbc.core.RowMapper;
import org.springframework.stereotype.Repository;

import java.sql.ResultSet;
import java.sql.SQLException;
import java.time.LocalDateTime;
import java.util.List;

/**
 * 容器隔离记录表访问。异常巡检确认时按当时箱内清单批量追加；
 * 复核放行仅更新状态与复核字段，original_location 快照永不改写。
 */
@Repository
public class ContainerIsolationRepository {

    private static final IsolationRowMapper ROW_MAPPER = new IsolationRowMapper();

    private final JdbcTemplate jdbc;

    public ContainerIsolationRepository(JdbcTemplate jdbc) {
        this.jdbc = jdbc;
    }

    /**
     * 追加一条 QUARANTINED 隔离记录，保留隔离时容器位置快照。
     */
    public void insert(long inspectionId, String evidenceKey, String containerKey,
                       String originalLocation, LocalDateTime now) {
        jdbc.update("""
                        INSERT INTO container_isolation
                            (inspection_id, evidence_key, container_key, original_location, status,
                             review_note, reviewed_by, reviewed_at, created_at)
                        VALUES (?, ?, ?, ?, ?, NULL, NULL, NULL, ?)
                        """,
                inspectionId, evidenceKey, containerKey, originalLocation,
                IsolationStatus.QUARANTINED.name(), now);
    }

    /**
     * 按巡检记录查询隔离清单（按隔离写入顺序）。
     */
    public List<ContainerIsolation> findByInspectionId(long inspectionId) {
        return jdbc.query(
                "SELECT * FROM container_isolation WHERE inspection_id = ? ORDER BY id",
                ROW_MAPPER, inspectionId);
    }

    /**
     * 查询容器当前仍待复核（QUARANTINED）的隔离记录（调用前必须已锁定容器行）。
     */
    public List<ContainerIsolation> findOpenByContainerKey(String containerKey) {
        return jdbc.query(
                "SELECT * FROM container_isolation WHERE container_key = ? AND status = ? ORDER BY id",
                ROW_MAPPER, containerKey, IsolationStatus.QUARANTINED.name());
    }

    /**
     * 复核放行：仅当仍为 QUARANTINED 时写入复核结论与时刻，历史不可覆盖。
     *
     * @return 是否成功放行
     */
    public boolean release(long id, String reviewedBy, String reviewNote, LocalDateTime reviewedAt) {
        int updated = jdbc.update("""
                        UPDATE container_isolation
                        SET status = ?, reviewed_by = ?, review_note = ?, reviewed_at = ?
                        WHERE id = ? AND status = ?
                        """,
                IsolationStatus.RELEASED.name(), reviewedBy, reviewNote, reviewedAt,
                id, IsolationStatus.QUARANTINED.name());
        return updated == 1;
    }

    private static final class IsolationRowMapper implements RowMapper<ContainerIsolation> {
        @Override
        public ContainerIsolation mapRow(ResultSet rs, int rowNum) throws SQLException {
            return new ContainerIsolation(
                    rs.getLong("id"),
                    rs.getLong("inspection_id"),
                    rs.getString("evidence_key"),
                    rs.getString("container_key"),
                    rs.getString("original_location"),
                    IsolationStatus.valueOf(rs.getString("status")),
                    rs.getString("review_note"),
                    rs.getString("reviewed_by"),
                    rs.getObject("reviewed_at", LocalDateTime.class),
                    rs.getObject("created_at", LocalDateTime.class));
        }
    }
}

package com.example.starter.evidence;

import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.jdbc.core.RowMapper;
import org.springframework.stereotype.Repository;

import java.sql.ResultSet;
import java.sql.SQLException;
import java.time.LocalDateTime;
import java.util.List;

/**
 * 证物位置轨迹表访问。每次放入容器追加一条；移出时仅回填 removed_at，
 * 历史轨迹不随复核或后续移动改写。
 */
@Repository
public class EvidencePlacementRepository {

    private static final PlacementRowMapper ROW_MAPPER = new PlacementRowMapper();

    private final JdbcTemplate jdbc;

    public EvidencePlacementRepository(JdbcTemplate jdbc) {
        this.jdbc = jdbc;
    }

    /**
     * 追加一条放入轨迹，位置取放入时容器位置快照。
     */
    public void insert(String evidenceKey, String containerKey, String location, LocalDateTime placedAt) {
        jdbc.update("""
                        INSERT INTO evidence_placement
                            (evidence_key, container_key, location, placed_at, removed_at)
                        VALUES (?, ?, ?, ?, NULL)
                        """,
                evidenceKey, containerKey, location, placedAt);
    }

    /**
     * 移出时回填当前在箱轨迹的移出时刻（调用前必须已锁定容器行与证物行）。
     */
    public void closeActive(String evidenceKey, LocalDateTime removedAt) {
        jdbc.update("""
                        UPDATE evidence_placement SET removed_at = ?
                        WHERE evidence_key = ? AND removed_at IS NULL
                        """,
                removedAt, evidenceKey);
    }

    /**
     * 按证物查询全部位置轨迹（按发生顺序），复核放行不改写。
     */
    public List<EvidencePlacement> findByEvidenceKey(String evidenceKey) {
        return jdbc.query(
                "SELECT * FROM evidence_placement WHERE evidence_key = ? ORDER BY id",
                ROW_MAPPER, evidenceKey);
    }

    private static final class PlacementRowMapper implements RowMapper<EvidencePlacement> {
        @Override
        public EvidencePlacement mapRow(ResultSet rs, int rowNum) throws SQLException {
            return new EvidencePlacement(
                    rs.getLong("id"),
                    rs.getString("evidence_key"),
                    rs.getString("container_key"),
                    rs.getString("location"),
                    rs.getObject("placed_at", LocalDateTime.class),
                    rs.getObject("removed_at", LocalDateTime.class));
        }
    }
}

