        assertThat(place("alice", uniqueKey("BOX"), evidenceA).getResponse().getStatus())
                .isEqualTo(404);
        // 不存在的证物返回 404
        assertThat(place("alice", containerKey, uniqueKey("EV")).getResponse().getStatus())
                .isEqualTo(404);
