    @Test
    void brokenSealOnEmptyContainerConfirmsWithoutIsolationItems() throws Exception {
        String containerKey = uniqueKey("BOX");
        assertThat(createContainer("alice", containerKey, "证物室-6号柜").getResponse().getStatus())
